/* one header, included by the service and by the proxy */
typedef struct {
    int (*call)(void *self, const req_t *req, resp_t *out);
} svc_vtbl_t;

static int proxy_call(void *self, const req_t *req, resp_t *out) {
    proxy_t *p = self;
    metrics_begin(p, req);
    int rc = p->real->vtbl->call(p->real, req, out);   /* delegate unchanged */
    return metrics_end(p, req, rc);                    /* same contract, same codes */
}

