static int (*real_connect)(int, const struct sockaddr *, socklen_t);

int connect(int fd, const struct sockaddr *addr, socklen_t len) {
    if (!real_connect)
        real_connect = dlsym(RTLD_NEXT, "connect");    /* resolve once, cache */
    metrics_count(addr);
    return real_connect(fd, addr, len);                /* delegate unchanged */
}
